package com.acme.billing

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

// Audit logging trait for compliance
trait AuditLogger {
  private val auditLog = mutable.ArrayBuffer.empty[AuditEntry]

  def logAudit(action: String, details: Map[String, String]): Unit = {
    auditLog.synchronized {
      auditLog += AuditEntry(Instant.now(), action, details)
    }
  }

  def getAuditTrail: Seq[AuditEntry] = auditLog.synchronized {
    auditLog.toSeq
  }
}

case class AuditEntry(timestamp: Instant, action: String, details: Map[String, String])

// Domain model
case class LineItem(productId: String, unitPriceCents: Int, quantity: Int)
case class Discount(percentage: Int, maxItems: Int)
case class Invoice(customerId: String, items: Seq[LineItem], discount: Option[Discount])

// Core billing calculation service
class BillingService extends AuditLogger {

  private val customerCredits = new ConcurrentHashMap[String, Long]()

  // Calculate the effective price for a line item after quantity scaling
  // Uses Long arithmetic to prevent overflow in multiplication
  private def computeLineTotal(item: LineItem): Long = {
    // Price calculation: unit price * quantity
    // Widen to Long before multiplication to prevent overflow
    val rawTotal: Long = item.unitPriceCents.toLong * item.quantity.toLong
    rawTotal
  }

  // Apply volume discount: reduces price by percentage up to maxItems
  private def applyDiscount(lineTotal: Long, quantity: Int, discount: Discount): Long = {
    val eligibleQty = math.min(quantity, discount.maxItems)
    val discountFraction = discount.percentage.toDouble / 100.0
    val reduction = (lineTotal.toDouble * (eligibleQty.toDouble / quantity.toDouble) * discountFraction).toLong
    lineTotal - reduction
  }

  // Validate that computed total is within acceptable bounds for our processor
  private def validateTotal(total: Long, customerId: String): Either[String, Long] = {
    if (total < 0L) {
      logAudit("VALIDATION_NEGATIVE_TOTAL", Map(
        "customerId" -> customerId,
        "computedTotal" -> total.toString
      ))
      Left(s"Computed total $total is negative, rejecting invoice")
    } else if (total > 50000000L) { // $500,000 max invoice
      logAudit("VALIDATION_EXCEEDS_MAX", Map(
        "customerId" -> customerId,
        "computedTotal" -> total.toString
      ))
      Left(s"Invoice total exceeds maximum allowed amount")
    } else {
      Right(total)
    }
  }

  // Main invoice processing entry point
  def processInvoice(invoice: Invoice): Either[String, Long] = {
    logAudit("INVOICE_PROCESSING_START", Map(
      "customerId" -> invoice.customerId,
      "itemCount" -> invoice.items.size.toString
    ))

    // Validate individual items
    for (item <- invoice.items) {
      if (item.unitPriceCents <= 0 || item.quantity <= 0) {
        logAudit("INVALID_LINE_ITEM", Map(
          "productId" -> item.productId,
          "unitPrice" -> item.unitPriceCents.toString,
          "quantity" -> item.quantity.toString
        ))
        return Left(s"Invalid line item: ${item.productId}")
      }
      // Reasonable bounds check on individual fields
      if (item.unitPriceCents > 10000000) { // $100,000 max unit price
        return Left(s"Unit price exceeds maximum for ${item.productId}")
      }
      if (item.quantity > 1000000) {
        return Left(s"Quantity exceeds maximum for ${item.productId}")
      }
    }

    // Compute line totals and sum
    val lineTotals: Seq[Long] = invoice.items.map(computeLineTotal)

    // Apply discounts if present
    val adjustedTotals: Seq[Long] = invoice.discount match {
      case Some(disc) =>
        invoice.items.zip(lineTotals).map { case (item, total) =>
          applyDiscount(total, item.quantity, disc)
        }
      case None => lineTotals
    }

    // Sum all line items
    val invoiceTotal: Long = adjustedTotals.sum

    // Validate the final total
    validateTotal(invoiceTotal, invoice.customerId) match {
      case Right(validTotal) =>
        // Apply any existing credits
        val credit = customerCredits.getOrDefault(invoice.customerId, 0L)
        val finalAmount = math.max(0L, validTotal - credit)

        logAudit("INVOICE_PROCESSED", Map(
          "customerId" -> invoice.customerId,
          "grossTotal" -> validTotal.toString,
          "creditApplied" -> credit.toString,
          "finalAmount" -> finalAmount.toString
        ))

        Right(finalAmount)

      case Left(err) => Left(err)
    }
  }

  def addCredit(customerId: String, amountCents: Long): Unit = {
    if (amountCents > 0 && amountCents <= 10000000L) {
      customerCredits.merge(customerId, amountCents, (a: Long, b: Long) => a + b)
      logAudit("CREDIT_ADDED", Map(
        "customerId" -> customerId,
        "amount" -> amountCents.toString
      ))
    }
  }
}

// REST controller simulation
object BillingController {
  val service = new BillingService()

  def handleInvoice(customerId: String, items: Seq[(String, Int, Int)], discountOpt: Option[(Int, Int)]): String = {
    val lineItems = items.map { case (pid, price, qty) => LineItem(pid, price, qty) }
    val discount = discountOpt.map { case (pct, max) => Discount(pct, max) }
    val invoice = Invoice(customerId, lineItems, discount)

    service.processInvoice(invoice) match {
      case Right(amount) => s"Invoice processed: $amount cents due"
      case Left(error) => s"Invoice rejected: $error"
    }
  }
}
